const { __unstable__loadDesignSystem } = require("tailwindcss");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const css = "@theme { --tracking-tighter: -0.05em; --tracking-tight: -0.025em; --tracking-normal: 0em; --tracking-wide: 0.025em; --tracking-wider: 0.05em; --tracking-widest: 0.1em; }\n@tailwind utilities;";
(async () => {
  let ds;
  try { ds = await __unstable__loadDesignSystem(css, { base: "/tmp" }); } catch (e) { broken("loadDesignSystem threw: " + e.message); }
  if (typeof ds.canonicalizeCandidates !== "function") broken("no canonicalizeCandidates");
  const out = ds.candidatesToCss(["-tracking-tighter", "tracking-wider"]);
  if (!out[0] || !out[1] || !out[0].includes("letter-spacing") || !out[1].includes("letter-spacing")) broken("unexpected tracking CSS: " + JSON.stringify(out));
  const got = ds.canonicalizeCandidates(["-tracking-tighter"]);
  if (!Array.isArray(got) || got.length !== 1) broken("unexpected result " + JSON.stringify(got));
  if (["-tracking-tighter", "tracking-[0.05em]", "-tracking-[-0.05em]"].includes(got[0])) symptom("canonicalizeCandidates did not turn -tracking-tighter into tracking-wider");
  if (got[0] !== "tracking-wider") broken("unexpected canonical form " + got[0]);
  console.log("OK: -tracking-tighter canonicalizes to tracking-wider");
})().catch(e => broken(String((e && e.message) || e)));

